<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$notice='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$status=(string)($_POST['status']??'');if(!$id||!in_array($status,['active','suspended'],true))$error='Invalid customer update.';else{db()->prepare("UPDATE users SET status=? WHERE id=? AND role='customer'")->execute([$status,$id]);$notice='Customer account updated.';}}
$q=trim((string)($_GET['q']??''));$sql="SELECT u.id,u.name,u.email,u.phone,u.status,u.created_at,COUNT(o.id) AS order_count FROM users u LEFT JOIN orders o ON o.user_id=u.id WHERE u.role='customer'";$params=[];if($q!==''){$sql.=' AND (u.name LIKE ? OR u.email LIKE ?)';$params=["%{$q}%","%{$q}%"];}$sql.=' GROUP BY u.id ORDER BY u.created_at DESC LIMIT 100';$stmt=db()->prepare($sql);$stmt->execute($params);$customers=$stmt->fetchAll();$adminTitle='Customers · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Customers</h1><?php if($notice||$error): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?><form class="mt-5 flex max-w-lg gap-2"><input class="form-control" type="search" name="q" value="<?= e($q) ?>" placeholder="Search name or email"><button class="rounded-full bg-forest px-5 text-sm text-white">Search</button></form><section class="mt-6 overflow-x-auto bg-white p-5"><table class="w-full min-w-[700px] text-left text-sm"><thead class="text-xs uppercase text-gray-500"><tr><th class="py-3">Customer</th><th>Phone</th><th>Orders</th><th>Joined</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($customers as $customer): ?><tr class="border-t border-black/5"><td class="py-3"><?= e($customer['name']) ?><br><span class="text-xs text-gray-500"><?= e($customer['email']) ?></span></td><td><?= e($customer['phone']??'—') ?></td><td><?= (int)$customer['order_count'] ?></td><td><?= e(date('M j, Y',strtotime($customer['created_at']))) ?></td><td class="capitalize"><?= e($customer['status']) ?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$customer['id'] ?>"><input type="hidden" name="status" value="<?= $customer['status']==='active'?'suspended':'active' ?>"><button class="underline"><?= $customer['status']==='active'?'Suspend':'Reactivate' ?></button></form></td></tr><?php endforeach; ?></tbody></table></section>
<?php require __DIR__.'/../../includes/admin-footer.php'; ?>
